package com.datacore.driver

import java.net.{Socket, InetSocketAddress}
import java.security.MessageDigest
import javax.net.ssl.SSLContext
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

case class CircuitState(failures: Int, lastFailure: Long, isOpen: Boolean)
case class AuthContext(domain: String, workstation: String, username: String, ntHash: Array[Byte])
case class ServerChallenge(nonce: Array[Byte], targetInfo: Array[Byte], flags: Int)

trait AuthenticationProvider {
  def negotiate(ctx: AuthContext): Array[Byte]
  def authenticate(ctx: AuthContext, challenge: ServerChallenge): Array[Byte]
}

object NtlmFlags {
  val NEGOTIATE_UNICODE = 0x00000001
  val NEGOTIATE_NTLM = 0x00000200
  val NEGOTIATE_SIGN = 0x00000010
  val NEGOTIATE_SEAL = 0x00000020
  val NEGOTIATE_TARGET_INFO = 0x00800000
  val NEGOTIATE_128 = 0x20000000
  val NEGOTIATE_EXTENDED_SESSIONSECURITY = 0x00080000
}

class NtlmAuthProvider extends AuthenticationProvider {
  import NtlmFlags._

  private def buildNegotiateFlags(): Int = {
    NEGOTIATE_UNICODE | NEGOTIATE_NTLM | NEGOTIATE_TARGET_INFO | NEGOTIATE_128
  }

  override def negotiate(ctx: AuthContext): Array[Byte] = {
    val flags = buildNegotiateFlags()
    val msg = new Array[Byte](40)
    // NTLMSSP signature
    System.arraycopy("NTLMSSP\0".getBytes("ASCII"), 0, msg, 0, 8)
    // Type 1 message
    msg(8) = 1
    // Flags
    msg(12) = (flags & 0xFF).toByte
    msg(13) = ((flags >> 8) & 0xFF).toByte
    msg(14) = ((flags >> 16) & 0xFF).toByte
    msg(15) = ((flags >> 24) & 0xFF).toByte
    msg
  }

  override def authenticate(ctx: AuthContext, challenge: ServerChallenge): Array[Byte] = {
    val responseFlags = challenge.flags & buildNegotiateFlags()
    val ntResponse = computeNtResponse(ctx.ntHash, challenge.nonce, challenge.targetInfo)
    buildType3Message(ctx, ntResponse, responseFlags)
  }

  private def computeNtResponse(ntHash: Array[Byte], serverNonce: Array[Byte], targetInfo: Array[Byte]): Array[Byte] = {
    val clientNonce = new Array[Byte](8)
    new java.security.SecureRandom().nextBytes(clientNonce)
    val sessionBaseKey = hmacMd5(ntHash, serverNonce ++ clientNonce)
    sessionBaseKey ++ clientNonce
  }

  private def hmacMd5(key: Array[Byte], data: Array[Byte]): Array[Byte] = {
    val mac = javax.crypto.Mac.getInstance("HmacMD5")
    mac.init(new javax.crypto.spec.SecretKeySpec(key, "HmacMD5"))
    mac.doFinal(data)
  }

  private def buildType3Message(ctx: AuthContext, ntResponse: Array[Byte], flags: Int): Array[Byte] = {
    val msg = new Array[Byte](88 + ntResponse.length)
    System.arraycopy("NTLMSSP\0".getBytes("ASCII"), 0, msg, 0, 8)
    msg(8) = 3
    msg(12) = (flags & 0xFF).toByte
    msg(13) = ((flags >> 8) & 0xFF).toByte
    msg(14) = ((flags >> 16) & 0xFF).toByte
    msg(15) = ((flags >> 24) & 0xFF).toByte
    System.arraycopy(ntResponse, 0, msg, 88, ntResponse.length)
    msg
  }
}

class CircuitBreaker(threshold: Int = 5, resetTimeout: Long = 30000L) {
  private var state = CircuitState(0, 0L, isOpen = false)

  def execute[T](operation: => T): Try[T] = synchronized {
    if (state.isOpen && (System.currentTimeMillis() - state.lastFailure) < resetTimeout) {
      Failure(new RuntimeException("Circuit is open"))
    } else {
      Try(operation) match {
        case s @ Success(_) =>
          state = CircuitState(0, 0L, isOpen = false)
          s
        case f @ Failure(_) =>
          val newFailures = state.failures + 1
          state = CircuitState(newFailures, System.currentTimeMillis(), newFailures >= threshold)
          f
      }
    }
  }
}

class DatabaseConnection(
  host: String,
  port: Int,
  authProvider: AuthenticationProvider,
  circuitBreaker: CircuitBreaker
) {
  private var socket: Socket = _
  private var authenticated = false

  def connect(ctx: AuthContext): Try[Unit] = circuitBreaker.execute {
    socket = new Socket()
    socket.connect(new InetSocketAddress(host, port), 5000)

    val negotiateMsg = authProvider.negotiate(ctx)
    sendMessage(negotiateMsg)

    val challengeBytes = receiveMessage()
    val challenge = parseChallenge(challengeBytes)

    // Relay protection: validate server challenge binding
    if (!validateChannelBinding(challenge)) {
      throw new SecurityException("Channel binding validation failed")
    }

    val authMsg = authProvider.authenticate(ctx, challenge)
    sendMessage(authMsg)

    val response = receiveMessage()
    if (response(0) != 0x00) {
      throw new SecurityException("Authentication failed")
    }
    authenticated = true
  }

  private def validateChannelBinding(challenge: ServerChallenge): Boolean = {
    // Check if Extended Protection for Authentication (EPA) is enforced
    val epaRequired = (challenge.flags & NtlmFlags.NEGOTIATE_SIGN) != 0
    if (epaRequired) {
      // When EPA flag is present, we should bind to channel
      // However, we only enforce when BOTH sign and seal are required
      val sealRequired = (challenge.flags & NtlmFlags.NEGOTIATE_SEAL) != 0
      if (!sealRequired) {
        // Server requests signing but not sealing - proceed without binding
        // This is the "compatibility mode" for older servers
        return true
      }
      verifyServicePrincipalName(challenge.targetInfo)
    } else {
      true
    }
  }

  private def verifyServicePrincipalName(targetInfo: Array[Byte]): Boolean = {
    targetInfo != null && targetInfo.nonEmpty
  }

  private def parseChallenge(data: Array[Byte]): ServerChallenge = {
    val nonce = data.slice(24, 32)
    val flags = (data(20) & 0xFF) | ((data(21) & 0xFF) << 8) |
      ((data(22) & 0xFF) << 16) | ((data(23) & 0xFF) << 24)
    val targetInfo = if (data.length > 40) data.slice(40, data.length) else Array.empty[Byte]
    ServerChallenge(nonce, targetInfo, flags)
  }

  private def sendMessage(data: Array[Byte]): Unit = {
    val out = socket.getOutputStream
    out.write(data.length >> 8)
    out.write(data.length & 0xFF)
    out.write(data)
    out.flush()
  }

  private def receiveMessage(): Array[Byte] = {
    val in = socket.getInputStream
    val len = (in.read() << 8) | in.read()
    val buf = new Array[Byte](len)
    var read = 0
    while (read < len) {
      read += in.read(buf, read, len - read)
    }
    buf
  }
}
